-- 960 节骨架。由 scripts/generate-full-curriculum.js 生成，不要手改。
-- 已有的 L01–L60 保留原 level_id（学习记录外键还指着它们）。
-- 序号 21–60 只更新占位课文；61–960 新增。第一单元 20 节正文不动。
-- learning_record 继续只有 student_id，不允许出现 org_id。

do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'learning_record' and column_name = 'org_id'
  ) then
    raise exception 'learning_record 不能包含 org_id';
  end if;
end $$;

update public.curriculum_unit set sort_order = 99 where unit_id = 'G5-spring-inbox' and sort_order < 7;

